import Combine
import Foundation

func multiplyPipeline(numbers: [Int], multiplier: Int) -> [Int] {
    var output: [Int] = []
    _ = numbers.publisher
        .map { $0 * multiplier }
        .sink { output.append($0) }
    return output
}

let result = multiplyPipeline(numbers: [1, 2, 3], multiplier: 10)
print("Multiplied: \(result)")

