import Combine
import Foundation

func filterPositiveNumbers(input: [Int]) -> [Int] {
    var results: [Int] = []
    _ = input.publisher
        .filter { $0 > 0 }
        .sink { results.append($0) }
    return results
}

let positives = filterPositiveNumbers(input: [-2, 0, 5, -1, 10])
print("Positives: \(positives)")
